const $=id=>document.getElementById(id);
let rows=[],settings={},record=null,dirty=false,pending=null,classResultsRequest=0,classReady=false;
const params=new URLSearchParams(location.hash.slice(1));let token=params.get('group')||'';const classToken=params.get('class')||'';
function status(message,error=false){$('status').textContent=message;$('status').className='message'+(error?' error':'');}
function initialRows(){return[{time:0,vol:0},...Array.from({length:5},()=>({time:'',vol:''}))];}
function canSave(){const temp=$('measurement-temp').value,team=$('team-name').value.trim();return classReady&&!!token&&!!$('selected-class').value.trim()&&!!team&&Array.from(team).length<=100&&temp!==''&&Number.isFinite(Number(temp))&&Number(temp)>=0&&Number(temp)<=60;}
function updateSaveAvailability(){$('submit').disabled=!canSave();}
function changed(){updateSaveAvailability();dirty=true;pending=null;status('未保存の変更があります。「保存してH₂O₂濃度を表示」を押してください。');document.querySelectorAll('[data-concentration]').forEach(e=>e.textContent='—');}
function render(){const body=$('rows');body.replaceChildren();let j=0;rows.forEach((r,i)=>{const tr=document.createElement('tr'),number=document.createElement('td');number.textContent=i===0?'初期':i;number.dataset.label='記録';tr.append(number);for(const [key,name]of[['time','時間'],['vol','捕集体積']]){const td=document.createElement('td'),input=document.createElement('input');td.dataset.label=key==='time'?`時間（${settings.unit||'min'}）`:'酸素累積量（mL）';input.type='number';input.inputMode='decimal';input.min=0;input.step='any';input.value=r[key];input.readOnly=i===0&&key==='time';input.setAttribute('aria-label',`${i+1}行目の${name}`);input.oninput=()=>{rows[i][key]=input.value;changed();};td.append(input);tr.append(td);}const c=document.createElement('td');c.dataset.concentration='';c.dataset.label='H₂O₂濃度（mol/L）';const value=r.time!==''||r.vol!==''?record?.concentrations?.[j++]?.c:null;c.textContent=!dirty&&value!=null?Number(value).toPrecision(4):'—';tr.append(c);const td=document.createElement('td'),remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.disabled=i===0;remove.setAttribute('aria-label',`${i+1}行目を削除`);remove.onclick=()=>{rows.splice(i,1);changed();render();};td.append(remove);tr.append(td);body.append(tr);});}
function displayRecord(value){record=value;$('team-name').value=value?.team_label||'';$('measurement-temp').value=value?.temperature??'';rows=value?.rows?.map(r=>({time:value.unit?Number(r.time)*(value.unit==='min'?60:1)/(settings.unit==='min'?60:1):r.time,vol:r.vol}))||initialRows();if(value?.input==='interval'&&settings.input==='total'){let total=0;rows=rows.map((r,i)=>{total=i===0?Number(r.vol):total+Number(r.vol);return{...r,vol:total};});}while(rows.length<6)rows.push({time:'',vol:''});dirty=false;pending=null;render();updateSaveAvailability();$('saved').textContent=value?'保存日時：'+new Date(value.created_at).toLocaleString('ja-JP'):'まだ保存されていません。';}
async function load(){if(dirty&&!confirm('未保存の入力を破棄して、この端末の保存記録を読み込みますか？'))return;try{const data=await LabAPI.rpc('lab_student_open',{p_token:token});settings=data.settings;classReady=typeof data.label==='string'&&!!data.label.trim();$('selected-class').value=classReady?data.label:'';$('group-label').textContent=data.label;$('timehead').textContent=`時間（${settings.unit}）`;$('volhead').textContent=(settings.input==='total'?'酸素累積量':'区間の増加体積')+'（mL）';const dl=$('conditions');dl.replaceChildren();for(const[label,value]of[['大気圧',settings.pressure+' Pa'],['反応液の全体積',settings.volume+' mL'],['水蒸気補正',settings.wet?'あり':'なし']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}displayRecord(data.record);$('student-form').hidden=false;$('student-form').disabled=false;status(data.record?.warning||'班名・時間・酸素累積量・実験温度を入力し、保存してください。');return true;}catch(e){status(e.message,true);return false;}}
$('add').onclick=()=>{if(rows.length>=101){status('測定は100行までです。',true);return;}rows.push({time:'',vol:''});changed();render();bodyFocusLast();};
function bodyFocusLast(){$('rows').lastElementChild?.querySelector('input')?.focus();}

$('submit').onclick=async()=>{if(!classReady||!token||!$('selected-class').value.trim()){status('クラスを選択してから保存してください。',true);$('entry-class').focus();return;}const filled=rows.filter(r=>r.time!==''||r.vol!=='');if(filled.some(r=>r.time===''||r.vol==='')){status('入力した行の時間・体積を両方記入してください。',true);return;}const temperature=$('measurement-temp').value;if(temperature===''||!Number.isFinite(Number(temperature))||Number(temperature)<0||Number(temperature)>60){status('実験温度を0～60 ℃で入力してください。',true);$('measurement-temp').focus();return;}const team=$('team-name').value.trim();if(!team||Array.from(team).length>100){status('班名を1～100文字で入力してください。',true);$('team-name').focus();return;}if(!pending)pending={id:crypto.randomUUID(),rows:filled,temperature:Number(temperature),team};$('student-form').disabled=true;status('サーバーに保存しています…');try{const saved=await LabAPI.rpc('lab_student_save',{p_token:token,p_rows:pending.rows,p_request_id:pending.id,p_temperature:pending.temperature,p_team_label:pending.team});displayRecord(saved);status(saved.warning||'保存しました。教員もこの記録を確認できます。');}catch(e){status(e.message,true);}finally{$('student-form').disabled=false;updateSaveAvailability();}};
$('measurement-temp').oninput=changed;$('team-name').oninput=changed;
function freshToken(){return Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');}
function deviceToken(groupId){const key='lab-device:'+classToken+':'+groupId;try{let value=localStorage.getItem(key);if(!/^[a-f0-9]{64}$/.test(value||'')){value=freshToken();localStorage.setItem(key,value);}return value;}catch{return freshToken();}}
$('class-entry').onsubmit=async e=>{e.preventDefault();const groupId=$('entry-class').value;if(!groupId){status('クラスを選択してください。',true);return;}const button=e.currentTarget.querySelector('button');button.disabled=true;try{const candidate=deviceToken(groupId);await LabAPI.rpc('lab_course_enter',{p_token:classToken,p_group_id:groupId,p_device_token:candidate});token=candidate;$('class-entry').hidden=true;if(!await load())$('class-entry').hidden=false;}catch(error){status(error.message,true);}finally{button.disabled=false;}};
async function openClass(){try{const c=await LabAPI.rpc('lab_course_open',{p_token:classToken});$('class-name').textContent=c.label;$('group-label').textContent=c.label+'：クラスを選択してください。';const select=$('entry-class');select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='クラスを選択してください';select.append(placeholder);for(const item of c.classes||[]){const option=document.createElement('option');option.value=item.id;option.textContent=item.label;select.append(option);}$('class-entry').hidden=false;$('class-entry').querySelector('button').disabled=!(c.classes||[]).length;status((c.classes||[]).length?'クラスを選択して実験結果を入力してください。':'選択できるクラスがまだありません。教員に確認してください。');}catch(e){status(e.message,true);}}
$('change-class').onclick=async()=>{if(dirty&&!confirm('未保存の入力を破棄してクラスを選び直しますか？'))return;if(!classToken){location.href='./';return;}closeClassResults();classReady=false;$('selected-class').value='';updateSaveAvailability();token='';record=null;rows=[];dirty=false;pending=null;$('student-form').hidden=true;$('student-form').disabled=true;$('team-name').value='';$('measurement-temp').value='';$('rows').replaceChildren();await openClass();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
if(!LabAPI.ready())status('保存・認証の初期設定がまだ完了していません。教員に確認してください。',true);else if(/^[a-f0-9]{64}$/.test(classToken))openClass();else if(!/^[a-f0-9]{64}$/.test(token))status('教員から配布された講座共通リンクまたはクラス専用リンクで開いてください。',true);else load();

function closeClassResults(){classResultsRequest++;$('class-input-results').hidden=true;$('class-input-content').replaceChildren();}
$('close-class-results').onclick=closeClassResults;
$('view-class-results').onclick=async()=>{const request=++classResultsRequest,button=$('view-class-results');button.disabled=true;$('class-input-results').hidden=false;$('class-input-content').textContent='提出結果を読み込んでいます…';try{const response=await LabAPI.rpc('lab_student_class_inputs',{p_token:token});if(request!==classResultsRequest)return;$('class-input-title').textContent=response.label+' の提出結果';const box=$('class-input-content');box.replaceChildren();if(!response.records.length){const p=document.createElement('p');p.className='help';p.textContent='まだ提出された結果はありません。';box.append(p);}for(const record of response.records){const section=document.createElement('section');section.className='class-input-team';const title=document.createElement('h3');title.textContent=record.team_label||'班名未設定の旧記録';section.append(title);const date=document.createElement('p');date.className='help';date.textContent='保存日時：'+new Date(record.created_at).toLocaleString('ja-JP');section.append(date);const scroll=document.createElement('div');scroll.className='scroll';const table=document.createElement('table'),head=document.createElement('tr');for(const label of['時間（'+(record.unit==='min'?'min':'s')+'）',record.input==='interval'?'入力値：区間酸素量（mL）':'酸素累積量（mL）','実験温度（℃）']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const value of record.rows){const row=document.createElement('tr');for(const v of[value.time,value.vol,record.temperature]){const cell=document.createElement('td');cell.textContent=v===null||v===undefined?'—':String(v);row.append(cell);}table.append(row);}scroll.append(table);section.append(scroll);box.append(section);}$('class-input-results').scrollIntoView?.({behavior:'smooth',block:'start'});}catch(error){if(request===classResultsRequest)$('class-input-content').textContent=error.message;}finally{button.disabled=false;}};
